pub fn ear_clip_polygon(points: &[[f32; 2]]) -> Vec<[f32; 2]> {
    if points.len() < 3 {
        return Vec::new();
    }
    let mut indices: Vec<usize> = (0..points.len()).collect();
    let mut triangles = Vec::new();
    let mut guard = 0usize;
    while indices.len() > 3 && guard < points.len() * points.len() {
        guard += 1;
        let mut ear_found = false;
        for i in 0..indices.len() {
            let prev = indices[(i + indices.len() - 1) % indices.len()];
            let curr = indices[i];
            let next = indices[(i + 1) % indices.len()];
            let a = points[prev];
            let b = points[curr];
            let c = points[next];
            let cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
            if cross <= 0.0 {
                continue;
            }
            let mut contains = false;
            for &idx in &indices {
                if idx == prev || idx == curr || idx == next {
                    continue;
                }
                let p = points[idx];
                if point_in_triangle(p, a, b, c) {
                    contains = true;
                    break;
                }
            }
            if contains {
                continue;
            }
            triangles.push(a);
            triangles.push(b);
            triangles.push(c);
            indices.remove(i);
            ear_found = true;
            break;
        }
        if !ear_found {
            break;
        }
    }
    if indices.len() == 3 {
        triangles.push(points[indices[0]]);
        triangles.push(points[indices[1]]);
        triangles.push(points[indices[2]]);
    }
    triangles
}

fn point_in_triangle(p: [f32; 2], a: [f32; 2], b: [f32; 2], c: [f32; 2]) -> bool {
    let d1 = sign(p, a, b);
    let d2 = sign(p, b, c);
    let d3 = sign(p, c, a);
    let has_neg = d1 < 0.0 || d2 < 0.0 || d3 < 0.0;
    let has_pos = d1 > 0.0 || d2 > 0.0 || d3 > 0.0;
    !(has_neg && has_pos)
}

/// 🎨️ Per-vertex tint, multiplied with the per-INSTANCE colour in `WORLD3D_SHADER` — a mesh that
/// declares no `Mesh3dField::Colors` uploads opaque white here and shades exactly as before. It is
/// what lets a terrain tile carry the CONTINUOUS hypsometric ramp React samples from a texture
/// (`getHypsometricTexture` in `🗺️WorldTerrainLayer/🟦️.tsx`) instead of being split into flat bands.
#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
pub struct World3dVertex {
    pub position: [f32; 3],
    pub normal: [f32; 3],
    pub color: [f32; 4],
    pub uv: [f32; 2],
    pub surface_uvs:[[f32;2];4],
    pub tangent:[f32;4],
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
pub struct World3dGlobals {
    pub view_proj: [f32; 16],
    pub shadow_view_proj: [f32; 16],
    pub camera_position: [f32; 4],
    pub light_dir: [f32; 4],
    pub ambient: [f32; 4],
    pub sun: [f32; 4],
    pub material: [f32; 4],
    pub material_emissive: [f32; 4],
    pub shadow: [f32; 4],
}

impl World3dGlobals {
    fn from_pass(pass: &ScenePass3d) -> Self {
        Self {
            view_proj: pass.view_proj,
            shadow_view_proj: pass.shadow.view_proj,
            camera_position: [pass.camera_position[0], pass.camera_position[1], pass.camera_position[2], 0.0],
            light_dir: [pass.light_dir[0], pass.light_dir[1], pass.light_dir[2], 0.0],
            ambient: [pass.lighting.ambient_color[0], pass.lighting.ambient_color[1], pass.lighting.ambient_color[2], pass.lighting.ambient_intensity],
            sun: [pass.lighting.sun_color[0], pass.lighting.sun_color[1], pass.lighting.sun_color[2], pass.lighting.sun_intensity],
            material: [pass.neutral_material.metalness, pass.neutral_material.roughness, pass.neutral_material.emissive_intensity, if pass.lighting.sun_enabled { 1.0 } else { 0.0 }],
            material_emissive: [pass.neutral_material.emissive[0], pass.neutral_material.emissive[1], pass.neutral_material.emissive[2], 0.0],
            shadow: [
                if pass.shadow.enabled { 1.0 } else { 0.0 },
                if pass.render_profile == SceneRenderProfile3d::SvgFlatLit { 1.0 } else { 0.0 },
                0.0,
                1.0,
            ],
        }
    }
}

