        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_line"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        pass.set_pipeline(&self.world_line_pipeline);
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_vertex_buffer(0, line_buffer);
        pass.draw(0..2, 0..1);
        Ok(())
    }

    /// 🎭️ Replays one completed World viewport through its image remap and physical viewport mask.
    pub fn encode_prepared_world_postprocess(
        &self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        composite: &PreparedCompositeTarget,
        pass_owner: &ScenePass3d,
        scene_scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        let curvilinear = pass_owner.curvilinear;
        let ellipse = pass_owner.viewport_mask == crate::wgpu::kernel_3d_scene::SceneViewportMask3d::Ellipse;
        if curvilinear.is_none() && !ellipse {
            return Err("prepared world postprocess pass had no descriptor");
        }
        let background = if ellipse { composite.postprocess_background_view().ok_or("prepared ellipse background snapshot was missing")? } else { &composite.postprocess_scene_scratch_view };
        let scale = self.surface_scale;
        let viewport = [pass_owner.viewport[0] * scale, pass_owner.viewport[1] * scale, pass_owner.viewport[2] * scale, pass_owner.viewport[3] * scale];
        let fov_strength = curvilinear.map_or([0.0, 0.0], |value| [value.fov_radians, value.strength]);
        queue.write_buffer(
            &self.postprocess_globals_buffer,
            0,
            bytemuck::bytes_of(&WorldPostprocessGlobals { viewport, surface_size: [composite.width as f32, composite.height as f32], fov_strength, modes: [u32::from(curvilinear.is_some()), u32::from(ellipse), 0, 0], clear_color: [0.0; 4] }),
        );
        composite.copy_to_postprocess_scene_scratch(encoder);
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_world_postprocess_bind_group"),
            layout: &self.postprocess_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: self.postprocess_globals_buffer.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(&composite.postprocess_scene_scratch_view) },
                wgpu::BindGroupEntry { binding: 2, resource: wgpu::BindingResource::Sampler(&composite.sampler) },
                wgpu::BindGroupEntry { binding: 3, resource: wgpu::BindingResource::TextureView(background) },
            ],
        });
        let mut render = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_postprocess"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: composite.world_encoded_view(), resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        render.set_viewport(viewport[0], viewport[1], viewport[2].max(1.0), viewport[3].max(1.0), 0.0, 1.0);
        let scene_scissor = self.physical_scissor(scene_scissor);
        render.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        render.set_pipeline(&self.world_postprocess_pipeline);
        render.set_bind_group(0, &bind_group, &[]);
        render.draw(0..6, 0..1);
        Ok(())
    }

    /// 🫧️ Paints an authored World background after the backdrop snapshot and before any 3D payload.
    pub fn encode_prepared_world_scene_clear(
        &self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        composite: &PreparedCompositeTarget,
        pass_owner: &ScenePass3d,
        scene_scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        let clear_color = pass_owner.clear_color.ok_or("prepared world scene clear had no color")?;
        let background = composite.postprocess_background_view().ok_or("prepared world scene clear had no background snapshot")?;
        let scale = self.surface_scale;
        let viewport = [pass_owner.viewport[0] * scale, pass_owner.viewport[1] * scale, pass_owner.viewport[2] * scale, pass_owner.viewport[3] * scale];
        queue.write_buffer(
            &self.postprocess_globals_buffer,
            0,
            bytemuck::bytes_of(&WorldPostprocessGlobals { viewport, surface_size: [composite.width as f32, composite.height as f32], fov_strength: [0.0; 2], modes: [0, 0, 1, 0], clear_color }),
        );
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_world_scene_clear_bind_group"),
            layout: &self.postprocess_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: self.postprocess_globals_buffer.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(background) },
                wgpu::BindGroupEntry { binding: 2, resource: wgpu::BindingResource::Sampler(&composite.sampler) },
                wgpu::BindGroupEntry { binding: 3, resource: wgpu::BindingResource::TextureView(background) },
            ],
        });
        let mut render = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_scene_clear"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: composite.world_encoded_view(), resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        render.set_viewport(viewport[0], viewport[1], viewport[2].max(1.0), viewport[3].max(1.0), 0.0, 1.0);
        let scene_scissor = self.physical_scissor(scene_scissor);
        render.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        render.set_pipeline(&self.world_postprocess_pipeline);
        render.set_bind_group(0, &bind_group, &[]);
        render.draw(0..6, 0..1);
        Ok(())
    }

    /// 🌫️ Builds one fixed blur mip for retained glass sampling.
    pub fn encode_prepared_blur_mip(&self, device: &wgpu::Device, queue: &wgpu::Queue, scene: &SceneColorTarget, mip: u32) -> Result<(), &'static str> {
        if mip == 0 || mip >= SCENE_MIP_LEVELS {
            return Err("prepared blur mip cursor was invalid");
        }
        let source = mip - 1;
        queue.write_buffer(&self.blur_globals_buffer, 0, bytemuck::bytes_of(&BlurGlobals { src_mip: 0.0, _pad: [0.0; 7] }));
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_blur_mip"),
            layout: &self.blur_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: self.blur_globals_buffer.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(scene.blur_scratch_mip_view(source)) },
                wgpu::BindGroupEntry { binding: 2, resource: wgpu::BindingResource::Sampler(scene.sampler()) },
            ],
        });
        let mut copy = device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some("prepared_blur_copy") });
        scene.copy_mip_to_blur_scratch(&mut copy, source);
        queue.submit(Some(copy.finish()));
        let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some("prepared_blur_mip") });
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_blur_mip"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: scene.mip_view(mip),
                resolve_target: None,
                ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT), store: wgpu::StoreOp::Store },
                depth_slice: None,
            })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_pipeline(&self.blur_downsample_pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.draw(0..6, 0..1);
        drop(pass);
        queue.submit(Some(encoder.finish()));
        Ok(())
    }

    /// 🪟 Encodes one retained glass region after the scene snapshot is resident.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_glass_scalar<'a>(
        &'a self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        view: &'a wgpu::TextureView,
        scene: &'a SceneColorTarget,
        frame_buffers: &'a mut FrameBuffers,
        region: &GlassRegion,
        scissor: ScissorRect,
        width: f32,
        height: f32,
    ) -> Result<(), &'static str> {
        let instance = GlassInstance { rect: region.rect, tint: [region.tint.r, region.tint.g, region.tint.b, region.tint.a], params: [region.radius, region.alpha, Theme::glass_mip_level(region.blur_px, SCENE_MIP_LEVELS - 1), region.saturate] };
        let Some(buffer) = frame_buffers.glass_instances.upload(device, queue, std::slice::from_ref(&instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_glass_scalar") else {
            return Err("prepared glass scalar buffer admission failed");
        };
        let scene_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("prepared_glass_scene"),
            layout: &self.scene_bind_group_layout,
            entries: &[wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(scene.sample_view()) }, wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(scene.sampler()) }],
        });
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_glass_scalar"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        set_pass_scissor(&mut pass, Some(scissor), self.surface_scale, width, height);
        pass.set_pipeline(&self.glass_pipeline);
        pass.set_bind_group(0, &self.glyph_bind_group, &[]);
        pass.set_bind_group(1, &scene_bind_group, &[]);
        pass.set_vertex_buffer(0, self.quad_vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, buffer);
        pass.draw(0..6, 0..1);
        Ok(())
    }

    /// 🖼️ Encodes one fixed scene-to-surface packet after all command pages are resident.
    pub fn blit_prepared_scene<'a>(&'a self, device: &wgpu::Device, encoder: &mut wgpu::CommandEncoder, view: &'a wgpu::TextureView, scene: &'a SceneColorTarget) {
        self.blit_sampled_color(device, encoder, view, scene.sample_view(), scene.sampler());
    }

    /// 🖼️ Copies the accumulated composite into a backdrop snapshot or the terminal surface.
    pub fn blit_prepared_composite<'a>(&'a self, device: &wgpu::Device, encoder: &mut wgpu::CommandEncoder, view: &'a wgpu::TextureView, composite: &'a PreparedCompositeTarget) {
        self.blit_sampled_color(device, encoder, view, &composite.view, &composite.sampler);
    }

    #[allow(clippy::too_many_arguments, reason = "one arg per GPU resource/dimension; grouping into a struct is a T2 restructure, out of scope")]
    #[cfg(test)]
    pub fn render_scene_content<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        scene: &'a SceneColorTarget,
        depth_view: Option<&'a wgpu::TextureView>,
        draw: &DrawList,
        mesh_store: &MeshGpuTable,
        raster_store: &RasterTextureTable,
        frame_buffers: &mut FrameBuffers,
        width: f32,
        height: f32,
        time_seconds: f32,
    ) {
        self.update_globals(queue, width, height, time_seconds);
        let scene_view = scene.mip_view(0);
        let world_upload = if depth_view.is_some() { self.upload_world_passes(device, queue, draw, frame_buffers, LayerBatchFilter::Backdrop) } else { None };
        let (prepared_holder, pass_index_map) = match world_upload {
            Some((prepared, map)) => (Some(prepared), map),
            None => (None, vec![None; draw.scene_passes.len()]),
        };
        let world_prepared = prepared_holder.as_deref();
        let (all_ui, all_vec, batches) = build_layer_batches(draw, LayerBatchFilter::Backdrop);
        let (mask_data, mask_ranges) = build_batch_masks(&batches, width, height);
        let mask_buffer = frame_buffers.mask_instances.upload(device, queue, &mask_data, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "silhouette_masks");
        let ui_buffer = if all_ui.is_empty() { None } else { frame_buffers.ui_instances.upload(device, queue, &all_ui, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "ui_instances") };
        let vector_buffer = if all_vec.is_empty() { None } else { frame_buffers.vector_vertices.upload(device, queue, &all_vec, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "vector_vertices") };
        let instance_buffer = frame_buffers.world_instances.slice();
        let line_buffer = frame_buffers.world_lines.slice();
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("ui_pass"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: scene_view,
                resolve_target: None,
                ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color { r: 0.05, g: 0.05, b: 0.06, a: 1.0 }), store: wgpu::StoreOp::Store },
                depth_slice: None,
            })],
            depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Clear(1.0), wgpu::LoadOp::Clear(0))),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        self.render_interleaved_layers(
            &mut pass,
            draw,
            &batches,
            mask_buffer.as_ref(),
            &mask_ranges,
            ui_buffer.as_ref(),
            vector_buffer.as_ref(),
            world_prepared,
            &pass_index_map,
            instance_buffer,
            line_buffer,
            mesh_store,
            width,
            height,
            depth_view.is_some(),
        );
        drop(pass);
        if draw.layers.iter().any(|layer| layer_matches_filter(layer, LayerBatchFilter::Backdrop) && !layer.raster_instances.is_empty()) {
            let mut raster_pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("ui_raster_pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: scene_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
                depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Load, wgpu::LoadOp::Clear(0))),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            self.draw_raster_layers(&mut raster_pass, raster_store, draw, frame_buffers, device, queue, width, height, LayerBatchFilter::Backdrop, false);
        }
        let (overlay_ui, overlay_vec, overlay_batches) = build_overlay_layer_batches(draw, LayerBatchFilter::Backdrop);
        if !overlay_ui.is_empty() || !overlay_vec.is_empty() {
            let (overlay_mask_data, overlay_mask_ranges) = build_batch_masks(&overlay_batches, width, height);
            let overlay_mask_buffer = frame_buffers.mask_instances.upload(device, queue, &overlay_mask_data, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "overlay_silhouette_masks");
            let overlay_ui_buffer = if overlay_ui.is_empty() { None } else { frame_buffers.ui_instances.upload(device, queue, &overlay_ui, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "overlay_ui_instances") };
            let overlay_vector_buffer = if overlay_vec.is_empty() { None } else { frame_buffers.vector_vertices.upload(device, queue, &overlay_vec, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "overlay_vector_vertices") };
            let mut overlay_pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("ui_overlay_pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: scene_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
                depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Load, wgpu::LoadOp::Clear(0))),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            self.render_interleaved_layers(
                &mut overlay_pass,
                draw,
                &overlay_batches,
                overlay_mask_buffer.as_ref(),
                &overlay_mask_ranges,
                overlay_ui_buffer.as_ref(),
                overlay_vector_buffer.as_ref(),
                None,
                &[],
                None,
                None,
                mesh_store,
                width,
                height,
                depth_view.is_some(),
            );
        }
        if draw.layers.iter().any(|layer| layer_matches_filter(layer, LayerBatchFilter::Backdrop) && !layer.overlay_raster_instances.is_empty()) {
            let mut raster_pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("ui_overlay_raster_pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: scene_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
                depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Load, wgpu::LoadOp::Clear(0))),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            self.draw_raster_layers(&mut raster_pass, raster_store, draw, frame_buffers, device, queue, width, height, LayerBatchFilter::Backdrop, true);
        }
    }

    #[cfg(test)]
    fn has_glass_foreground(draw: &DrawList) -> bool {
        let layer_content = draw.layers.iter().any(|layer| {
            layer.foreground_of.is_some()
                && (!layer.ui_instances.is_empty()
                    || !layer.vector_vertices.is_empty()
                    || !layer.raster_instances.is_empty()
                    || !layer.overlay_ui_instances.is_empty()
                    || !layer.overlay_vector_vertices.is_empty()
                    || !layer.overlay_raster_instances.is_empty())
        });
        let scene_content = draw.scene_passes.iter().any(|pass| layer_matches_filter(&draw.layers[pass.layer_index], LayerBatchFilter::Foreground));
        layer_content || scene_content
    }

