/// 🧩️ Re-export of the target-neutral draw-list/value types split into `draw_types.rs` (ticket
/// 26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS) — keeps every existing
/// `DrawList`/`UiInstance`/`ScissorRect`/... reference in this file resolving unchanged.
pub use super::draw_types::*;

pub const SCENE_MIP_LEVELS: u32 = 5;

#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
struct BlurGlobals {
    src_mip: f32,
    _pad: [f32; 7],
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
struct WorldPostprocessGlobals {
    viewport: [f32; 4],
    surface_size: [f32; 2],
    fov_strength: [f32; 2],
    modes: [u32; 4],
    clear_color: [f32; 4],
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
pub struct GlassInstance {
    pub rect: [f32; 4],
    pub tint: [f32; 4],
    pub params: [f32; 4],
}

pub struct SceneColorTarget {
    texture: wgpu::Texture,
    blur_scratch: wgpu::Texture,
    blur_scratch_mip_views: Vec<wgpu::TextureView>,
    world_encoded_view: wgpu::TextureView,
    sample_view: wgpu::TextureView,
    mip_views: Vec<wgpu::TextureView>,
    sampler: wgpu::Sampler,
    width: u32,
    height: u32,
}

impl SceneColorTarget {
    pub fn ensure(device: &wgpu::Device, target: &mut Option<Self>, width: u32, height: u32, format: wgpu::TextureFormat) {
        let width = width.max(1);
        let height = height.max(1);
        if let Some(existing) = target {
            if existing.width == width && existing.height == height {
                return;
            }
        }
        let world_encoded_format = format.remove_srgb_suffix();
        let texture = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("scene_color"),
            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
            mip_level_count: SCENE_MIP_LEVELS,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: world_encoded_format,
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_SRC,
            view_formats: &[format, world_encoded_format],
        });
        let blur_scratch = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("scene_blur_scratch"),
            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
            mip_level_count: SCENE_MIP_LEVELS,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: world_encoded_format,
            usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
            view_formats: &[format, world_encoded_format],
        });
        let blur_scratch_mip_views = (0..SCENE_MIP_LEVELS)
            .map(|level| {
                blur_scratch.create_view(&wgpu::TextureViewDescriptor {
                    label: Some(&format!("scene_blur_scratch_mip_{level}")),
                    format: Some(format),
                    dimension: Some(wgpu::TextureViewDimension::D2),
                    base_mip_level: level,
                    mip_level_count: Some(1),
                    ..Default::default()
                })
            })
            .collect();
        let sample_view = texture.create_view(&wgpu::TextureViewDescriptor {
            label: Some("scene_color_sample"),
            format: Some(format),
            dimension: Some(wgpu::TextureViewDimension::D2),
            base_mip_level: 0,
            mip_level_count: Some(SCENE_MIP_LEVELS),
            ..Default::default()
        });
        let world_encoded_view = texture.create_view(&wgpu::TextureViewDescriptor {
            label: Some("scene_color_world_encoded"),
            format: Some(world_encoded_format),
            dimension: Some(wgpu::TextureViewDimension::D2),
            base_mip_level: 0,
            mip_level_count: Some(1),
            ..Default::default()
        });
        let mip_views = (0..SCENE_MIP_LEVELS)
            .map(|level| {
                texture.create_view(&wgpu::TextureViewDescriptor {
                    label: Some(&format!("scene_color_mip_{level}")),
                    format: Some(format),
                    dimension: Some(wgpu::TextureViewDimension::D2),
                    base_mip_level: level,
                    mip_level_count: Some(1),
                    ..Default::default()
                })
            })
            .collect();
        let sampler =
            device.create_sampler(&wgpu::SamplerDescriptor { label: Some("scene_color_sampler"), mag_filter: wgpu::FilterMode::Linear, min_filter: wgpu::FilterMode::Linear, mipmap_filter: wgpu::MipmapFilterMode::Linear, ..Default::default() });
        *target = Some(Self { texture, blur_scratch, blur_scratch_mip_views, world_encoded_view, sample_view, mip_views, sampler, width, height });
    }

    pub fn mip_view(&self, level: u32) -> &wgpu::TextureView {
        &self.mip_views[level as usize]
    }

    pub fn sample_view(&self) -> &wgpu::TextureView {
        &self.sample_view
    }

    pub fn world_encoded_view(&self) -> &wgpu::TextureView {
        &self.world_encoded_view
    }

    pub fn sampler(&self) -> &wgpu::Sampler {
        &self.sampler
    }

    pub fn blur_scratch_mip_view(&self, level: u32) -> &wgpu::TextureView {
        &self.blur_scratch_mip_views[level as usize]
    }

    fn mip_extent(&self, level: u32) -> wgpu::Extent3d {
        wgpu::Extent3d { width: (self.width >> level).max(1), height: (self.height >> level).max(1), depth_or_array_layers: 1 }
    }

    pub fn copy_mip_to_blur_scratch(&self, encoder: &mut wgpu::CommandEncoder, src_mip: u32) {
        let extent = self.mip_extent(src_mip);
        encoder.copy_texture_to_texture(
            wgpu::TexelCopyTextureInfo { texture: &self.texture, mip_level: src_mip, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            wgpu::TexelCopyTextureInfo { texture: &self.blur_scratch, mip_level: src_mip, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            extent,
        );
    }
}

/// 🖼️ The surface-sized colour target a prepared frame composites into BEFORE it ever touches the
/// swapchain — the scene blit lands here, every glass region lands here, and only the terminal
/// present step copies it onto the acquired surface texture.
///
/// 🩸️ A swapchain texture is a SINGLE-TASK resource in a browser: WebGPU expires the canvas's
/// current texture at the end of the task that obtained it, and presents whatever it held at that
/// moment. The prepared present ladder is stepped across many host tasks, so acquiring in one task
/// and compositing in a later one presented the untouched (opaque black) texture and threw the
/// composite away — measured 6/6 on `26/09/17/WGPU-RENDERER-REACT-PARITY`: every black boot had its
/// acquire and its composite in different host pumps, every painted boot had them in the same one.
/// One extra full-surface blit buys an acquire→present span that cannot straddle a task.
pub struct PreparedCompositeTarget {
    texture: wgpu::Texture,
    view: wgpu::TextureView,
    world_encoded_view: wgpu::TextureView,
    postprocess_scene_scratch: wgpu::Texture,
    postprocess_scene_scratch_view: wgpu::TextureView,
    postprocess_background_scratch: Option<(wgpu::Texture, wgpu::TextureView)>,
    world_encoded_format: wgpu::TextureFormat,
    sampler: wgpu::Sampler,
    width: u32,
    height: u32,
}

impl PreparedCompositeTarget {
    pub fn ensure(device: &wgpu::Device, target: &mut Option<Self>, width: u32, height: u32, format: wgpu::TextureFormat) {
        let width = width.max(1);
        let height = height.max(1);
        if let Some(existing) = target {
            if existing.width == width && existing.height == height {
                return;
            }
        }
        let world_encoded_format = format.remove_srgb_suffix();
        let texture = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("prepared_composite_color"),
            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: world_encoded_format,
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_SRC,
            view_formats: &[format, world_encoded_format],
        });
        let view = texture.create_view(&wgpu::TextureViewDescriptor { label: Some("prepared_composite_color_view"), format: Some(format), dimension: Some(wgpu::TextureViewDimension::D2), ..Default::default() });
        let world_encoded_view = texture.create_view(&wgpu::TextureViewDescriptor { label: Some("prepared_composite_world_encoded_view"), format: Some(world_encoded_format), dimension: Some(wgpu::TextureViewDimension::D2), ..Default::default() });
        let postprocess_scene_scratch = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("prepared_postprocess_scene_scratch"),
            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: world_encoded_format,
            usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
            view_formats: &[world_encoded_format],
        });
        let postprocess_scene_scratch_view = postprocess_scene_scratch.create_view(&wgpu::TextureViewDescriptor { label: Some("prepared_postprocess_scene_scratch_view"), format: Some(world_encoded_format), dimension: Some(wgpu::TextureViewDimension::D2), ..Default::default() });
        let sampler = device.create_sampler(&wgpu::SamplerDescriptor { label: Some("prepared_composite_sampler"), mag_filter: wgpu::FilterMode::Linear, min_filter: wgpu::FilterMode::Linear, ..Default::default() });
        *target = Some(Self { texture, view, world_encoded_view, postprocess_scene_scratch, postprocess_scene_scratch_view, postprocess_background_scratch: None, world_encoded_format, sampler, width, height });
    }

    pub fn view(&self) -> &wgpu::TextureView {
        &self.view
    }

    pub fn world_encoded_view(&self) -> &wgpu::TextureView {
        &self.world_encoded_view
    }

    pub(crate) fn copy_to_readback(&self, encoder: &mut wgpu::CommandEncoder, buffer: &wgpu::Buffer, bytes_per_row: u32) {
        encoder.copy_texture_to_buffer(
            wgpu::TexelCopyTextureInfo { texture: &self.texture, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            wgpu::TexelCopyBufferInfo { buffer, layout: wgpu::TexelCopyBufferLayout { offset: 0, bytes_per_row: Some(bytes_per_row), rows_per_image: Some(self.height) } },
            wgpu::Extent3d { width: self.width, height: self.height, depth_or_array_layers: 1 },
        );
    }

    fn copy_to_postprocess_scene_scratch(&self, encoder: &mut wgpu::CommandEncoder) {
        encoder.copy_texture_to_texture(
            wgpu::TexelCopyTextureInfo { texture: &self.texture, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            wgpu::TexelCopyTextureInfo { texture: &self.postprocess_scene_scratch, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            wgpu::Extent3d { width: self.width, height: self.height, depth_or_array_layers: 1 },
        );
    }

    fn ensure_postprocess_background_scratch(&mut self, device: &wgpu::Device) {
        if self.postprocess_background_scratch.is_some() {
            return;
        }
        let texture = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("prepared_postprocess_background_scratch"),
            size: wgpu::Extent3d { width: self.width, height: self.height, depth_or_array_layers: 1 },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: self.world_encoded_format,
            usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
            view_formats: &[self.world_encoded_format],
        });
        let view = texture.create_view(&wgpu::TextureViewDescriptor { label: Some("prepared_postprocess_background_scratch_view"), format: Some(self.world_encoded_format), dimension: Some(wgpu::TextureViewDimension::D2), ..Default::default() });
        self.postprocess_background_scratch = Some((texture, view));
    }

    pub(crate) fn copy_to_postprocess_background_scratch(&mut self, device: &wgpu::Device, encoder: &mut wgpu::CommandEncoder) {
        self.ensure_postprocess_background_scratch(device);
        let texture = &self.postprocess_background_scratch.as_ref().expect("background scratch was ensured").0;
        encoder.copy_texture_to_texture(
            wgpu::TexelCopyTextureInfo { texture: &self.texture, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            wgpu::TexelCopyTextureInfo { texture, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            wgpu::Extent3d { width: self.width, height: self.height, depth_or_array_layers: 1 },
        );
    }

    fn postprocess_background_view(&self) -> Option<&wgpu::TextureView> {
        self.postprocess_background_scratch.as_ref().map(|(_, view)| view)
    }
}

