    /// 🌑 Encodes the fixed scene clear packet without traversing retained draw owners.
    pub fn clear_prepared_scene<'a>(&'a self, encoder: &mut wgpu::CommandEncoder, scene: &'a SceneColorTarget, depth_view: Option<&'a wgpu::TextureView>, clear: wgpu::Color) {
        let pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_scene_clear"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: scene.mip_view(0),
                resolve_target: None,
                ops: wgpu::Operations { load: wgpu::LoadOp::Clear(clear), store: wgpu::StoreOp::Store },
                depth_slice: None,
            })],
            depth_stencil_attachment: depth_view.map(|depth| stencil_attachment(depth, wgpu::LoadOp::Clear(1.0), wgpu::LoadOp::Clear(0))),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        drop(pass);
    }

    /// 🔹 Encodes one retained UI instance without collecting or traversing sibling layers.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_ui_scalar<'a>(
        &'a self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        raster_store: &'a RasterTextureTable,
        instance: &UiInstance,
        raster_key: Option<&str>,
        scissor: Option<ScissorRect>,
        width: f32,
        height: f32,
        time_seconds: f32,
    ) -> Result<(), &'static str> {
        self.update_globals(queue, width, height, time_seconds);
        let Some(buffer) = frame_buffers.ui_instances.upload(device, queue, std::slice::from_ref(instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_ui_scalar") else {
            return Err("prepared UI scalar buffer admission failed");
        };
        let bind_group = match raster_key {
            Some(key) => &raster_store.get(key).ok_or("prepared raster scalar texture was missing")?.bind_group,
            None => &self.glyph_bind_group,
        };
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_ui_scalar"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        set_pass_scissor(&mut pass, scissor, self.surface_scale, width, height);
        pass.set_pipeline(&self.ui_pipeline);
        pass.set_bind_group(0, bind_group, &[]);
        pass.set_vertex_buffer(0, self.quad_vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, buffer);
        pass.draw(0..6, 0..1);
        Ok(())
    }

    /// 🔺 Encodes one retained vector triangle without staging a dynamic batch.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_vector_triangle<'a>(
        &'a self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        vertices: &[VectorVertex],
        scissor: Option<ScissorRect>,
        width: f32,
        height: f32,
        time_seconds: f32,
    ) -> Result<(), &'static str> {
        if vertices.len() != 3 {
            return Err("prepared vector scalar was not one triangle");
        }
        self.update_globals(queue, width, height, time_seconds);
        let Some(buffer) = frame_buffers.vector_vertices.upload(device, queue, vertices, wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_vector_triangle") else {
            return Err("prepared vector triangle buffer admission failed");
        };
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_vector_triangle"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        set_pass_scissor(&mut pass, scissor, self.surface_scale, width, height);
        pass.set_pipeline(&self.vector_pipeline);
        pass.set_bind_group(0, &self.glyph_bind_group, &[]);
        pass.set_vertex_buffer(0, buffer);
        pass.draw(0..3, 0..1);
        Ok(())
    }

    /// 🌑️ Clears the lazily enlarged directional depth map before this scene's bounded caster
    /// scalars. Disabled shadows leave the one-pixel fallback resident and issue no GPU work.
    pub fn encode_prepared_world_shadow_begin(&mut self, device: &wgpu::Device, encoder: &mut wgpu::CommandEncoder, pass_owner: &ScenePass3d) {
        if !pass_owner.shadow.enabled {
            return;
        }
        if self.world_shadow_target.size != pass_owner.shadow.map_size {
            self.world_shadow_target = WorldShadowTarget::new(device, &self.world_shadow_bind_group_layout, pass_owner.shadow.map_size);
        }
        let _pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_shadow_clear"),
            color_attachments: &[],
            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment { view: &self.world_shadow_target.view, depth_ops: Some(wgpu::Operations { load: wgpu::LoadOp::Clear(1.0), store: wgpu::StoreOp::Store }), stencil_ops: None }),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
    }

    /// 🌑️ Encodes one opaque caster into the scene's shadow map. One instance per call keeps
    /// cancellation and replacement at the same scalar boundary as the color pass.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_shadow_instance<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        frame_buffers: &'a mut FrameBuffers,
        mesh_store: &'a MeshGpuTable,
        pass_owner: &ScenePass3d,
        mesh_key: &str,
        mesh_version: u64,
        instance: &crate::wgpu::kernel_3d_scene::Instance3d,
    ) -> Result<bool, &'static str> {
        if !pass_owner.shadow.enabled {
            return Ok(false);
        }
        if self.world_shadow_target.size != pass_owner.shadow.map_size {
            return Err("prepared world shadow map was not begun");
        }
        let Some(mesh) = mesh_store.get_versioned(mesh_key, mesh_version) else { return Ok(false) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let gpu_instance =
            World3dGpuInstance::from_instance(instance.model.to_cols_array_m(), instance.color, instance.material.preserve_vertex_color, instance.material.emissive_intensity, instance.material.metalness, instance.material.roughness, false);
        let Some(instance_buffer) = frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_shadow_instance") else {
            return Err("prepared world shadow instance buffer admission failed");
        };
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_shadow_instance"),
            color_attachments: &[],
            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment { view: &self.world_shadow_target.view, depth_ops: Some(wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }), stencil_ops: None }),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_pipeline(&self.world_shadow_pipeline);
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_vertex_buffer(0, mesh.vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.set_index_buffer(mesh.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
        Ok(true)
    }

    /// 🌐 Encodes one retained mesh instance under one scene-pass owner, answering whether it drew.
    ///
    /// 🕰️ A mesh key/version that is not resident draws NOTHING and is not a fault, exactly as
    /// [`Self::encode_prepared_world_textured`] answers a raster whose pixels have not landed. A miss
    /// used to be a FATAL `present_step` fault that quarantined the whole surface for the rest of the
    /// session — one unbacked ghost draw killed the puzzle3d journey mid-flight (ticket
    /// 26/09/17/WGPU-RENDERER-REACT-PARITY, `📓️w11a-prepared-world-mesh-missing.md`). React simply
    /// renders nothing until its loader resolves, so the skip is the parity behaviour; the source-side
    /// residency law lives in `♾️infinite/🌍️world`'s `retain_ensured_world_draws`, and the skip is
    /// reported once per transition by the host so a regression there stays readable.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_instance<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        mesh_store: &'a MeshGpuTable,
        pass_owner: &ScenePass3d,
        mesh_key: &str,
        mesh_version: u64,
        instance: &crate::wgpu::kernel_3d_scene::Instance3d,
        receives_shadow: bool,
        translucent: bool,
        scissor: ScissorRect,
        width: f32,
        height: f32,
    ) -> Result<bool, &'static str> {
        let Some(mesh) = mesh_store.get_versioned(mesh_key, mesh_version) else { return Ok(false) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let gpu_instance =
            World3dGpuInstance::from_instance(instance.model.to_cols_array_m(), instance.color, instance.material.preserve_vertex_color, instance.material.emissive_intensity, instance.material.metalness, instance.material.roughness, receives_shadow);
        let Some(instance_buffer) = frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_instance") else {
            return Err("prepared world instance buffer admission failed");
        };
        let scale = self.surface_scale;
        let viewport = pass_owner.viewport;
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(true);
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_instance"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        pass.set_pipeline(if translucent { &self.world_pipeline_translucent } else { &self.world_pipeline });
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
        pass.set_vertex_buffer(0, mesh.vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.set_index_buffer(mesh.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
        pass.set_viewport(0.0, 0.0, width * scale, height * scale, 0.0, 1.0);
        Ok(true)
    }

    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_material<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        mesh_store: &'a MeshGpuTable,
        raster_store: &'a RasterTextureTable,
        pass_owner: &ScenePass3d,
        draw_owner: &crate::wgpu::kernel_3d_scene::SceneMaterialDraw3d,
        instance: &crate::wgpu::kernel_3d_scene::Instance3d,
        scissor: ScissorRect,
        width: f32,
        height: f32,
    ) -> Result<bool, &'static str> {
        let Some(mesh) = mesh_store.get_versioned(&draw_owner.mesh_key, draw_owner.mesh_version) else { return Ok(false) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let painted_bind_group;
        let instance_buffer = match &draw_owner.material {
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Standard => {
                painted_bind_group = None;
                let gpu_instance = World3dGpuInstance::from_instance(
                    instance.model.to_cols_array_m(),
                    instance.color,
                    instance.material.preserve_vertex_color,
                    instance.material.emissive_intensity,
                    instance.material.metalness,
                    instance.material.roughness,
                    pass_owner.shadow.enabled,
                );
                frame_buffers
                    .world_instances
                    .upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_standard_translucent")
                    .ok_or("prepared world standard translucent buffer admission failed")?
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Painted { texture_key } => {
                let Some(raster) = raster_store.get(texture_key) else { return Ok(true) };
                painted_bind_group = Some(device.create_bind_group(&wgpu::BindGroupDescriptor {
                    label: Some("world3d_painted_bind_group"),
                    layout: &self.scene_bind_group_layout,
                    entries: &[wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&raster.view) }, wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(&self.world_plane_sampler) }],
                }));
                let gpu_instance = World3dGpuInstance::from_instance(
                    instance.model.to_cols_array_m(),
                    instance.color,
                    instance.material.preserve_vertex_color,
                    instance.material.emissive_intensity,
                    instance.material.metalness,
                    instance.material.roughness,
                    pass_owner.shadow.enabled,
                );
                frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_painted").ok_or("prepared world painted buffer admission failed")?
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Celebration { stops, angle } => {
                painted_bind_group = None;
                let gpu_instance = World3dCelebrationGpuInstance::from_instance(instance.model.to_cols_array_m(), *stops, *angle, instance.color[3]);
                frame_buffers
                    .world_celebration_instances
                    .upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_celebration")
                    .ok_or("prepared world celebration buffer admission failed")?
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Authored(material) => {
                let keys = [&material.base_color_texture, &material.metallic_roughness_texture, &material.normal_texture, &material.occlusion_texture, &material.emissive_texture];
                painted_bind_group = if keys.iter().any(|key| key.is_some()) {
                    let mut entries = Vec::with_capacity(10);
                    for (role,key) in keys.into_iter().enumerate() {
                        let view = if let Some(key) = key { let Some(raster) = raster_store.get(key) else { return Ok(true) }; &raster.view } else { &self.world_authored_white };
                        let descriptor = if role == 0 { material.texture_sampler } else { material.additional_texture_samplers[role-1] };
                        let sampler = &self.world_material_samplers.iter().find(|(candidate,_)| *candidate == descriptor).ok_or("authored material sampler was not prepared")?.1;
                        entries.push(wgpu::BindGroupEntry { binding: role as u32 * 2, resource: wgpu::BindingResource::TextureView(view) });
                        entries.push(wgpu::BindGroupEntry { binding: role as u32 * 2 + 1, resource: wgpu::BindingResource::Sampler(sampler) });
                    }
                    Some(device.create_bind_group(&wgpu::BindGroupDescriptor { label: Some("world3d_authored_bind_group"), layout: &self.world_authored_bind_group_layout, entries: &entries }))
                } else { None };
                let gpu_instance = World3dGpuInstance::from_authored(instance.model.to_cols_array_m(), material, pass_owner.shadow.enabled);
                frame_buffers.world_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_authored").ok_or("prepared world authored buffer admission failed")?
            }
        };
        let scale = self.surface_scale;
        let viewport = pass_owner.viewport;
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(true);
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_material"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        match &draw_owner.material {
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Standard => {
                pass.set_pipeline(&self.world_standard_translucent_pipeline);
                pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Painted { .. } => {
                pass.set_pipeline(if draw_owner.translucent { &self.world_painted_pipeline_translucent } else { &self.world_painted_pipeline });
                pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
                pass.set_bind_group(2, painted_bind_group.as_ref().expect("painted branch owns its texture bind group"), &[]);
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Celebration { .. } => {
                pass.set_pipeline(if draw_owner.translucent { &self.world_celebration_pipeline_translucent } else { &self.world_celebration_pipeline });
                pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
            }
            crate::wgpu::kernel_3d_scene::SceneMaterialKind3d::Authored(material) => {
                if painted_bind_group.is_some() {
                    pass.set_pipeline(match (draw_owner.translucent, material.double_sided) {
                        (false, false) => &self.world_authored_painted_front_pipeline,
                        (false, true) => &self.world_authored_painted_double_pipeline,
                        (true, false) => &self.world_authored_painted_front_translucent_pipeline,
                        (true, true) => &self.world_authored_painted_double_translucent_pipeline,
                    });
                    pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                    pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
                    pass.set_bind_group(2, painted_bind_group.as_ref().expect("authored texture owns its bind group"), &[]);
                } else {
                    pass.set_pipeline(match (draw_owner.translucent, material.double_sided) {
                        (false, false) => &self.world_authored_front_pipeline,
                        (false, true) => &self.world_pipeline,
                        (true, false) => &self.world_pipeline_translucent,
                        (true, true) => &self.world_authored_double_translucent_pipeline,
                    });
                    pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
                    pass.set_bind_group(1, &self.world_shadow_target.bind_group, &[]);
                }
            }
        }
        pass.set_vertex_buffer(0, mesh.vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.set_index_buffer(mesh.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
        let first = draw_owner.first_index.min(mesh.index_count);
        let end = first.saturating_add(draw_owner.index_count).min(mesh.index_count);
        if first < end {
            pass.draw_indexed(first..end, 0, 0..1);
        }
        pass.set_viewport(0.0, 0.0, width * scale, height * scale, 0.0, 1.0);
        Ok(true)
    }

    /// 🖼️ Encodes one retained TEXTURED world quad — the reference underlay — under one scene-pass
    /// owner.
    ///
    /// 🩸️ `ScenePass3d::textured_draws` has been measured by `advance_pipeline` and carried in every
    /// prepared packet since the scene pass existed, and `DrawMeasureCursor::PassTextured*` walked it
    /// page by page — but nothing ever ENCODED it: `encode_prepared_draw_scalar` had no arm for those
    /// cursors and `WORLD3D_TEXTURED_PIPELINE` was declared in the shader contract as "inferred —
    /// unwired in draw.rs". The plan underlay the puzzle3d playground decodes, admits and submits
    /// (`textured=1` on both surfaces) could therefore never paint on any target, ever
    /// (ticket 26/09/17/WGPU-RENDERER-REACT-PARITY packet W5c).
    ///
    /// 🕰️ A key whose pixels have not landed yet draws NOTHING and is not a fault: the underlay's
    /// instance is published the frame its url appears, long before the image is fetched and decoded,
    /// exactly as React returns `null` from `WorldReferencePlaneItem` until `media` resolves.
    #[allow(clippy::too_many_arguments, reason = "one fixed owner per GPU boundary")]
    pub fn encode_prepared_world_textured<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &'a wgpu::TextureView,
        depth_view: &'a wgpu::TextureView,
        frame_buffers: &'a mut FrameBuffers,
        raster_store: &'a RasterTextureTable,
        pass_owner: &ScenePass3d,
        instance: &crate::wgpu::kernel_3d_scene::TexturedInstance3d,
        scissor: ScissorRect,
    ) -> Result<(), &'static str> {
        let Some(raster) = raster_store.get(&instance.texture_key) else { return Ok(()) };
        let globals = World3dGlobals::from_pass(pass_owner);
        self.world_globals_ring.ensure_slots(device, &self.world_bind_group_layout, 1);
        self.world_globals_ring.write_passes(queue, std::slice::from_ref(&globals));
        let gpu_instance = World3dTexturedGpuInstance::from_instance(instance.model.to_cols_array_m(), instance.background, instance.appearance);
        let Some(instance_buffer) = frame_buffers.world_textured_instances.upload(device, queue, std::slice::from_ref(&gpu_instance), wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST, "prepared_world_textured") else {
            return Err("prepared world textured buffer admission failed");
        };
        let texture_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("world3d_textured_bind_group"),
            layout: &self.scene_bind_group_layout,
            entries: &[wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&raster.view) }, wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(&self.world_plane_sampler) }],
        });
        let scale = self.surface_scale;
        let viewport = pass_owner.viewport;
        let scene_scissor = self.physical_scissor(scissor);
        if scene_scissor.w == 0 || scene_scissor.h == 0 {
            return Ok(());
        }
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("prepared_world_textured"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: color_view, resolve_target: None, ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store }, depth_slice: None })],
            depth_stencil_attachment: Some(stencil_attachment(depth_view, wgpu::LoadOp::Load, wgpu::LoadOp::Load)),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_viewport(viewport[0] * scale, viewport[1] * scale, viewport[2] * scale, viewport[3] * scale, 0.0, 1.0);
        pass.set_scissor_rect(scene_scissor.x, scene_scissor.y, scene_scissor.w, scene_scissor.h);
        pass.set_pipeline(&self.world_textured_pipeline);
        pass.set_bind_group(0, &self.world_globals_ring.bind_group, &[self.world_globals_ring.offset_for_slot(0)]);
        pass.set_bind_group(1, &texture_bind_group, &[]);
        pass.set_vertex_buffer(0, self.world_plane_vertex_buffer.slice(..));
        pass.set_vertex_buffer(1, instance_buffer);
        pass.draw(0..6, 0..1);
        Ok(())
    }

